import numpy as np, itertools
lam=1.5406
def cell_mono(a,b,c,beta):
    b_=np.radians(beta)
    return np.array([[a,0,0],[0,b,0],[c*np.cos(b_),0,c*np.sin(b_)]])
def cell_hex(a,c):
    return np.array([[a,0,0],[-a/2,a*np.sqrt(3)/2,0],[0,0,c]])
cells={'Ibam':cell_mono(12.19104,6.10797,4.88206,113.4903),'P-3m1':cell_hex(4.24553,5.26514),'R-3m':cell_mono(9.26233,5.35031,6.92524,116.4678)}
for name,A in cells.items():
    B=np.linalg.inv(A).T
    res=[]
    for h,k,l in itertools.product(range(-8,9),repeat=3):
        if (h,k,l)==(0,0,0): continue
        g=B@np.array([h,k,l]); d=1/np.linalg.norm(g)
        s=lam/(2*d)
        tt2=2*np.degrees(np.arcsin(s))
        if 10<tt2<70: res.append((round(tt2,2),(h,k,l)))
    res=sorted(set(res))
    print(name, [r for r in res][:40])

